(* [comment removed for export] *)
Lemma mem_ok_piece HL LK cr Aw M model M1 (Wp : Z -> Prop) :
  ri_inv HI (HL ++ LB) FF LK cr Aw M (vml_of model) -> mem_ok M -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
