(* [comment removed for export] *)
Lemma pv_facts HL LK cr Aw M model : ri_inv HI (HL ++ LB) FF LK cr Aw M (vml_of model) -> mem_ok M -> NESKA.pv_ok ar FF M S v pv ->
  L5.defined M pv 1 /\ byte_at M (HeapIfaceA.S pv) 0 /\ (pv + 1 <= v \/ v + 24 <= pv)
  /\ 4096 <= pv /\ pv + 1 <= 2 ^ 47 /\ 7036928 <= pv /\ (pv + 1 <= S - 12288 \/ S <= pv) /\ (2147446784 + 17592186048512 <= pv \/ pv + 1 <= 2147446784)
  /\ (forall LBc sp' scr', sp' <= S -> aclient L ar LBc FF sp' scr' pv) /\ L5A.avis (ahid Aw model) pv 1
