  ri_inv HI (HL ++ LB) FF LK cr Aw M (vml_of model) -> mem_ok M ->
  ri_inv HI (HL1 ++ LB) FF LK1 cr1 Aw1 M1 (vml_of model1) -> mem_ok M1 ->
  incl (NESK.sink_own k') HL -> incl (NESK.sink_own k') HL1 ->
