  sk = NESK.SK 0 0 0 ->
  getr R (reg 2) = Z_to_bv 64 (S - 160) -> getr R (reg 8) = Z_to_bv 64 (v + 8) -> getr R (reg 9) = Z_to_bv 64 v -> getr R (reg 18) = Z_to_bv 64 pv ->
